import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x = sc.nextDouble();
        double y = sc.nextDouble();
        double n = sc.nextDouble();

        int numerator = 0;
        int denominator = 1;
        double ratio = x / y;
        double closest_ratio = 0;

        for (int i = 1; i <= (int)n; ++i) {
            int floor_val = (int)Math.floor(ratio * i);
            int ceil_val = (int)Math.ceil(ratio * i);

            if (Math.abs(ratio - (double)floor_val / i) + 1e-15 < Math.abs(ratio - closest_ratio)) {
                numerator = floor_val;
                denominator = i;
                closest_ratio = (double)floor_val / i;
            }
            if (Math.abs(ratio - (double)ceil_val / i) + 1e-15 < Math.abs(ratio - closest_ratio)) {
                numerator = ceil_val;
                denominator = i;
                closest_ratio = (double)ceil_val / i;
            }
        }

        int g = gcd(numerator, denominator);
        System.out.println((numerator / g) + "/" + (denominator / g));
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
